function AuthorOverflowMenu({
  documentId,
  documentActions = [],
  onCopyId,
  onShareLink,
}: {
  documentId?: string | null;
  documentActions?: ReadonlyArray<OverflowMenuItem>;
  onCopyId?: () => void;
  onShareLink?: () => void;
}) {
  const documentItems: OverflowMenuItem[] = [];

  if (documentId && onCopyId) {
    documentItems.push({
      kind: "action",
      label: "Copy document id",
      shortcut: "⌘I",
      onSelect: onCopyId,
    });
  }
  if (onShareLink) {
    documentItems.push({
      kind: "action",
      label: "Share workspace link",
      shortcut: "⌘⇧S",
      onSelect: onShareLink,
    });
  }
  documentItems.push(...documentActions);

  const sections: OverflowMenuSection[] = [];
  if (documentItems.length > 0) {
    sections.push({ title: "Document", items: documentItems });
  }

  sections.push({
    title: "Reference",
    items: [
      { kind: "link", label: "Docs", href: "/docs" },
      { kind: "link", label: "API reference", href: "/docs/api" },
      { kind: "link", label: "OPF schema · v1", href: "/docs/opf" },
      {
        kind: "link",
        label: "pptx.gallery",
        href: "https://pptx.gallery",
        external: true,
      },
    ],
  });

  return <OverflowMenu sections={sections} />;
}

type AuthorSource = { text: string; format: Format };
type AuthorDraft = AuthorSource & { document: OPFDocument };
type PresetGroup = {
  editor: EditorSession;
  original: AuthorSource;
  expected: AuthorSource;
  undoDepth: number;
  redoDepth: number;
};
type PresetTransaction = {
  token: object;
  editor: EditorSession;
  before: OPFDocument;
  after: OPFDocument;
  expected: AuthorSource;
  result: AuthorSource;
  undoDepth: number;
  override?: CanvasSourceOverride;
  accepted: boolean;
};

function matchesPresetGroup(group: PresetGroup, source: AuthorSource, editor: EditorSession | null): boolean {
  if (!editor || group.editor !== editor || group.expected.text !== source.text || group.expected.format !== source.format) return false;
  const snapshot = editor.snapshot();
  return snapshot.undoDepth === group.undoDepth && snapshot.redoDepth === group.redoDepth;
}

export function AuthorShell({ initialSignedIn }: { initialSignedIn: boolean }) {
  const [inputMode, setInputMode] = useState<InputMode>("prompt");
  const [operationMode, setOperationMode] = useState<OperationMode>("auto");
  const [activityTab, setActivityTab] = useState<ActivityTabId>("agent");
  const [centerTab, setCenterTab] = useState<CenterTabId>("code");
  const [format, setFormatState] = useState<Format>("json");
  const sourceRef = useRef({ text: STARTER_OPF, format: "json" as Format });
  const [canvasSource] = useState(createCanvasSourceBridge);
  const rejectedCanvasChangeRef = useRef(0);
  const [presetToasts, setPresetToasts] = useState<ReadonlyArray<PresetAppliedToastData>>([]);
  const presetGroupRef = useRef<PresetGroup | null>(null);
  const presetTransactionRef = useRef<PresetTransaction | null>(null);
  const readySessionRef = useRef<EditorSession | null>(null);
  const invalidatePresetGroup = useCallback(() => {
    presetGroupRef.current = null;
    setPresetToasts((current) => current.length ? [] : current);
  }, []);
  // Every source/format writer updates the same guard before React renders.
  // Canvas commits and their export handlers can run in the same event.
  const setFormat = useCallback<Dispatch<SetStateAction<Format>>>((next) => {
    const value = typeof next === "function" ? next(sourceRef.current.format) : next;
    invalidatePresetGroup();
    sourceRef.current = { ...sourceRef.current, format: value };
    setFormatState(value);
  }, [invalidatePresetGroup]);
  const [cursorSelection, setCursorSelection] = useState<OpfCursorSelection | null>(null);
  const [pinnedPaths, setPinnedPaths] = useState<string[]>([]);
  const [localGallerySources, setLocalGallerySources] = useState<AuthorGallerySource[]>([]);
  const [accountGallerySources, setAccountGallerySources] = useState<AuthorGallerySource[]>([]);
  const [selectedToolName, setSelectedToolName] = useState("resolve.field");
  const [manualToolCalls, setManualToolCalls] = useState<AuthorToolCallRecord[]>([]);
  const [manualToolOutput, setManualToolOutput] = useState<ManualToolOutput>(null);
  // Until the refine/ask backend returns structured patches (DAT-TBD),
  // this stays null. Once it lands, set it from the run result. UI surfaces
  // (transcript card, sticky banner, Diff tab) all read from this state.
  const [pendingGhostEdit, setPendingGhostEdit] = useState<GhostEdit | null>(null);
  const ghostHunkCount = pendingGhostEdit
    ? pendingHunks(pendingGhostEdit).length
    : 0;
  const [prompt, setPrompt] = useState("");
  const [rawText, setRawText] = useState("");
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [snapshot, setSnapshot] = useState<AuthorThreadSnapshot | null>(null);
  const [pendingInitialAgentMessage, setPendingInitialAgentMessage] =
    useState<PendingInitialAgentMessage | null>(null);
  const [selectedRunId, setSelectedRunId] = useState<string | null>(null);
  const [selectedPreviewSlideIndex, setSelectedPreviewSlideIndex] = useState(0);
  const [previewSelectionPath, setPreviewSelectionPath] = useState<string | null>(null);
  const [libraryLauncher, setLibraryLauncher] = useState<LibraryLauncherState>({
    kind: "all",
    open: false,
  });
  const [selectedOpfDocumentId, setSelectedOpfDocumentId] = useState<string | null>(null);
  const [handoffOpf, setHandoffOpf] = useState<PublicAuthorOpfDocument | null>(null);
  const [acceptedOpfText, setAcceptedOpfText] = useState(STARTER_OPF);
  const [opfDraft, setOpfDraftState] = useState(STARTER_OPF);
  const writeSourceText = useCallback((text: string) => {
    sourceRef.current = { ...sourceRef.current, text };
    setOpfDraftState(text);
  }, []);
  const setOpfDraft = useCallback<Dispatch<SetStateAction<string>>>((next) => {
    const text = typeof next === "function" ? next(sourceRef.current.text) : next;
    // Includes root-replacement intent even when its bytes happen to match.
    invalidatePresetGroup();
    writeSourceText(text);
  }, [invalidatePresetGroup, writeSourceText]);
  const [isSending, setIsSending] = useState(false);
  const [surfaceError, setSurfaceError] = useState<string | null>(null);
  const [exportNotes, setExportNotes] = useState<string[] | null>(null);
  const [autoSubmitArmed, setAutoSubmitArmed] = useState(false);
  const [hydrationSettled, setHydrationSettled] = useState(false);
  const [pendingRestore, setPendingRestore] = useState<AuthorPendingSubmit | null>(null);
  const autoSubmitDidFireRef = useRef(false);
  const [localWorkspaceReady, setLocalWorkspaceReady] = useState(false);
  const [localWorkspaceWarning, setLocalWorkspaceWarning] = useState<string | null>(null);
  const [localVersions, setLocalVersions] = useState<AuthorLocalVersion[]>([]);
  const [copiedJson, setCopiedJson] = useState(false);
  const [copiedShare, setCopiedShare] = useState(false);
  const [copiedThreadId, setCopiedThreadId] = useState(false);
  const [copiedPayload, setCopiedPayload] = useState(false);
  const [busyExport, setBusyExport] = useState(false);
  const [busySaveLocal, setBusySaveLocal] = useState(false);
  const [editorJumpTarget, setEditorJumpTarget] = useState<OpfEditorJumpTarget | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const canvasRef = useRef<CanvasEditor | null>(null);
  const editorJumpIdRef = useRef(0);
  const lgLayout = useWideAuthorLayout();
  const { leftRem, rightRem, commit, usePersistedWidths } = useAuthorWorkbenchSplitSizes();

  const thread = snapshot?.thread ?? null;
  const threadId = thread?.id ?? null;
  const authorStorageMode: AuthorStorageMode = threadId ? "remote" : "local";
  const remoteAuthorAvailable = initialSignedIn || authorStorageMode === "remote";
  const latestOpf = snapshot?.latestOpf ?? null;
  const opfVersions = useMemo(() => {
    const versions = snapshot?.opfVersions ?? [];
    if (versions.length > 0) return versions;
    return latestOpf ? [latestOpf] : [];
  }, [latestOpf, snapshot?.opfVersions]);
  const selectedOpf =
    selectedOpfDocumentId && opfVersions.length > 0
      ? opfVersions.find((document) => document.id === selectedOpfDocumentId) ?? null
      : null;
  // Latest accepted OPF is the generated/applied version shown in the editor;
  // readOnly enforcement is delegated to AuthorEditPane while requests run.
  const activeOpf = selectedOpf ?? latestOpf ?? handoffOpf;
  const viewingHistoricalVersion = Boolean(
    thread?.latestOpfDocumentId &&
      activeOpf?.threadId === thread.id &&
      activeOpf.id !== thread.latestOpfDocumentId
  );
  const runs = useMemo(() => sortRuns(snapshot?.runs ?? []), [snapshot?.runs]);
  const messages = useMemo(() => snapshot?.messages ?? [], [snapshot?.messages]);
  const toolCatalog = useMemo(() => authorToolCatalog(), []);
  const effectiveGallerySources = useMemo(
    () => [...accountGallerySources, ...localGallerySources],
    [accountGallerySources, localGallerySources]
  );

  // Author intent dossier + preset matches are derived further below,
  // once `parseDraftState` and other state are available. See "intent
  // dossier" block.
  const [followUpChips, setFollowUpChips] = useState<ReadonlyArray<FollowUpChip>>([]);
  const [followUpLoading, setFollowUpLoading] = useState(false);
  const followUpRunRef = useRef<string | null>(null);
  const toolCalls = useMemo(
    () =>
      [
        ...manualToolCalls,
        ...runs.flatMap((run) => run.toolMeta?.toolCalls ?? []),
      ].sort((a, b) => Date.parse(b.startedAt) - Date.parse(a.startedAt)),
    [manualToolCalls, runs]
  );
  const selectedRun = runs.find((run) => run.id === selectedRunId) ?? runs[0] ?? null;
  const latestRun = runs[0] ?? null;
  const lastRunSummary: AuthorRunSummary | null = latestRun
    ? {
        op: latestRun.operation,
        at: formatRunTime(latestRun.createdAt),
        createdAt: latestRun.createdAt,
      }
    : null;
  const rejectedRunCount = runs.filter((run) => run.status === "rejected").length;
  const parseDraftState = useMemo(() => parseDocument(opfDraft, format), [opfDraft, format]);
  const parseAcceptedState = useMemo(
    () => parseDocument(acceptedOpfText, format),
    [acceptedOpfText, format]
  );
  const parseState = parseDraftState;
  const previewParseState = useMemo(() => {
    if (isSending) return parseAcceptedState;
    return parseDraftState;
  }, [isSending, parseAcceptedState, parseDraftState]);
  const lastValidPreviewRef = useRef<OPFDocument | undefined>(undefined);
  const previewState = useMemo(() => {
    const next = buildPreviewState(previewParseState);
    if (next.status === "ok") {
      lastValidPreviewRef.current = next.doc;
      return next;
    }
    if (next.status === "schema_error" && lastValidPreviewRef.current) {
      return { ...next, lastValid: lastValidPreviewRef.current };
    }
    return next;
  }, [previewParseState]);
  const previewDocument = previewState.status === "ok" ? previewState.doc : null;
  const jsonFieldCatalogs = useMemo(
    () => loadedCatalogsFromGallerySources(effectiveGallerySources),
    [effectiveGallerySources]
  );
  const validation = useMemo(
    () => (parseState.document ? validateOPF(parseState.document) : null),
    [parseState.document]
  );
  const onCanvasDocumentChange = useCallback((document: unknown, previous: unknown, event: EditorEvent) => {
    const pending = presetTransactionRef.current;
    const ownsTransaction = pending && event.type === "patch" && event.meta?.authorPresetTransaction === pending.token;
    if (ownsTransaction) presetTransactionRef.current = null;
    else invalidatePresetGroup();
    try {
      if (isSending) throw new Error("Wait for the current Author request before editing the preview.");
      if (ownsTransaction && (readySessionRef.current !== pending.editor
        || event.snapshot.undoDepth !== pending.undoDepth || event.snapshot.redoDepth !== 0
        || sourceRef.current.text !== pending.expected.text || sourceRef.current.format !== pending.expected.format
        || !sameJsonValue(previous, pending.before) || !sameJsonValue(document, pending.after))) {
        throw new Error("The draft changed before this preset edit could be applied. Your source was kept.");
      }
      const text = canvasSource.apply(sourceRef.current, { before: previous, after: document, event }, ownsTransaction ? pending.override : undefined);
      if (ownsTransaction && text !== pending.result.text) {
        throw new Error("The preset edit no longer matches the current source. Your source was kept.");
      }
      if (text !== sourceRef.current.text) writeSourceText(text);
      if (ownsTransaction) pending.accepted = true;
      return true;
    } catch (error) {
      invalidatePresetGroup();
      rejectedCanvasChangeRef.current++;
      canvasSource.clear();
      setSurfaceError(error instanceof Error ? error.message : "The source changed. Reopen the preview field to edit the current slide.");
      return false;
    }
  }, [canvasSource, invalidatePresetGroup, isSending, writeSourceText]);
  const recoverCanvasSource = useCallback(() => {
    const current = parseText(sourceRef.current.text, sourceRef.current.format);
    return current.ok && validateOPF(current.doc).valid ? current.doc : null;
  }, []);
  const canvasSession = useOpfEditorSession(
    validation?.valid ? parseState.document : null,
    onCanvasDocumentChange,
    recoverCanvasSource,
  );
  useEffect(() => {
    // The session hook installs its subscription before this readiness marker.
    const editor = canvasSession.editor;
    readySessionRef.current = editor;
    return () => { if (readySessionRef.current === editor) readySessionRef.current = null; };
  }, [canvasSession.editor]);
  const readCurrentDraft = useCallback(() => {
    const canvas = canvasRef.current;
    const rejectedBeforeCommit = rejectedCanvasChangeRef.current;
    if (canvas && (!canvas.commit() || !canvasSession.editor
      || rejectedCanvasChangeRef.current !== rejectedBeforeCommit)) return null;
    const source = sourceRef.current;
    const current = parseDocument(source.text, source.format);
    if (canvas && (!current.document || !sameJsonValue(current.document, canvasSession.editor!.document))) {
      setSurfaceError("The source changed while the preview was being edited. Your source was kept; reopen the preview before exporting.");
      return null;
    }
    return { ...source, document: current.document };
  }, [canvasSession.editor]);
  // The source tab temporarily unmounts the canvas. Keep its fonts available offline.
  useEffect(() => {
    let cancelled = false;
    let release: (() => void) | undefined;
    void acquireBrowserFonts().then(lease => {
      if (cancelled) lease.release(); else release = lease.release;
    }, cause => {
      if (!cancelled) setSurfaceError('Presentation fonts could not load: ' + (cause instanceof Error ? cause.message : String(cause)));
    });
    return () => { cancelled = true; release?.(); };
  }, []);
  const deckSummary = useMemo(() => summarizeDeck(parseState.document), [parseState.document]);
  const outputFilenameBase =
    deckSummary.filenameBase ||
    (activeOpf ? `author-thread-v${activeOpf.version}` : "author-output");
  const dirtyOpfDraft = acceptedOpfText !== opfDraft;
  const canPublishOutput =
    Boolean(parseState.document && validation?.valid) && !isSending;
  const cursorResolution = useMemo(
    () =>
      resolveOpfCursorPath({
        cursor: cursorSelection,
        format: "json",
        text: opfDraft,
      }),
    [cursorSelection, opfDraft]
  );
  const selectedPath =
    cursorResolution.status === "resolved" ? cursorResolution.path : null;
  const effectiveSelectedPath =
    selectedPath && selectedPath !== "$"
      ? selectedPath
      : defaultAuthorSelectionPath(parseState.document);

  // Author intent dossier — deterministic interpretation of user inputs
  // (prompt + raw text + upload summaries + selection + existing OPF).
  const authorIntent = useMemo(
    () =>
      deriveAuthorIntent({
        prompt,
        rawText,
        attachments: attachments.map((attachment) => ({
          name: attachment.name,
          summary: typeof attachment.text === "string"
            ? attachment.text.slice(0, 600)
            : undefined,
        })),
        selectedPath: effectiveSelectedPath,
        pinnedPaths,
        existingOpf: parseDraftState.document ?? null,
      }),
    [
      prompt,
      rawText,
      attachments,
      effectiveSelectedPath,
      pinnedPaths,
      parseDraftState.document,
    ]
  );

  // Gallery preset suggestions ranked by intent. Keyed on the scalar slot
  // values the matcher actually reads — not on the `authorIntent` object,
  // which is a fresh reference on every keystroke and would otherwise
  // re-walk the gallery for every keypress.
  const intentTopic = authorIntent.topic?.value;
  const intentAudience = authorIntent.audience?.value;
  const intentTone = authorIntent.tone?.value;
  const intentNarrative = authorIntent.narrative?.value;
  const intentDomain = authorIntent.domain?.value;
  const intentLength = authorIntent.length?.value;
  const presetMatches = useMemo(
    () =>
      matchGalleryPresets(authorIntent, {
        document: parseDraftState.document ?? null,
        sources: effectiveGallerySources,
        perKind: 3,
      }),
    // authorIntent itself is intentionally NOT in the deps — see comment above.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      intentTopic,
      intentAudience,
      intentTone,
      intentNarrative,
      intentDomain,
      intentLength,
      parseDraftState.document,
      effectiveGallerySources,
    ]
  );
  const payloadPreview = useMemo(
    () =>
      buildPayloadPreview({
        attachments,
        inputMode,
        operationMode,
        prompt,
        rawText,
        remoteAuthorAvailable,
        threadId: thread?.id,
        baseOpfDocumentId: thread?.latestOpfDocumentId,
        selectionPath: selectedPath && selectedPath !== "$" ? selectedPath : null,
        pinnedPaths,
      }),
    [
      attachments,
      inputMode,
      operationMode,
      pinnedPaths,
      prompt,
      rawText,
      remoteAuthorAvailable,
      selectedPath,
      thread?.id,
      thread?.latestOpfDocumentId,
    ]
  );
  const localAuthorMetadataIntent = useMemo(() => {
    if (thread || inputMode !== "prompt" || attachments.length > 0) return null;
    if (!parseState.document || !validation?.valid) return null;
    return parseAuthorMetadataIntent(prompt);
  }, [attachments.length, inputMode, parseState.document, prompt, thread, validation?.valid]);
  useEffect(() => {
    setSelectedOpfDocumentId(latestOpf?.id ?? null);
  }, [latestOpf?.id, thread?.id]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const result = readAuthorLocalWorkspace(window.localStorage);
    if (!result.ok) {
      setLocalWorkspaceWarning(result.error);
      setLocalVersions([]);
      setLocalWorkspaceReady(true);
      return;
    }
    if (result.workspace) {
      setFormat(result.workspace.format);
      setAcceptedOpfText(result.workspace.acceptedOpfText);
      setOpfDraft(result.workspace.opfDraft);
      setPinnedPaths(result.workspace.ui.pinnedPaths);
      setLocalVersions(result.workspace.localVersions);
      setLocalGallerySources(result.workspace.gallerySources);
      if (result.workspace.ui.centerTab) setCenterTab(result.workspace.ui.centerTab);
    } else {
      const starterWorkspace = createAuthorLocalWorkspace({
        acceptedOpfText: STARTER_OPF,
        format: "json",
        opfDraft: STARTER_OPF,
      });
      setLocalVersions(starterWorkspace.localVersions);
    }
    setLocalWorkspaceReady(true);
  }, [setFormat, setOpfDraft]);

  useEffect(() => {
    if (!localWorkspaceReady || authorStorageMode !== "local" || typeof window === "undefined") {
      return;
    }
    const workspace = createAuthorLocalWorkspace({
      acceptedOpfText,
      centerTab: centerTab === "preview" ? "preview" : "code",
      filename: outputFilenameBase,
      format,
      gallerySources: localGallerySources,
      localVersions,
      opfDraft,
      pinnedPaths,
      selectedPath: effectiveSelectedPath,
    });
    const result = writeAuthorLocalWorkspace(window.localStorage, workspace);
    if (!result.ok) {
      setLocalWorkspaceWarning(result.error);
    }
  }, [
    acceptedOpfText,
    authorStorageMode,
    centerTab,
    effectiveSelectedPath,
    format,
    localGallerySources,
    localVersions,
    localWorkspaceReady,
    opfDraft,
    outputFilenameBase,
    pinnedPaths,
  ]);

  useEffect(() => {
    if (!initialSignedIn) {
      setAccountGallerySources((current) => (current.length === 0 ? current : []));
      return;
    }
    let cancelled = false;
    fetchAccountGallerySourcesOnce()
      .then((sources) => {
        if (!cancelled) setAccountGallerySources(sources);
      })
      .catch(() => {
        if (!cancelled) setAccountGallerySources((current) => (current.length === 0 ? current : []));
      });
    return () => {
      cancelled = true;
    };
  }, [initialSignedIn]);

  useEffect(() => {
    const apply = (doc: unknown) => {
      const jsonText = toJsonText(doc);
      if (format === "json") {
        setAcceptedOpfText(jsonText);
        setOpfDraft(jsonText);
        return;
      }
      const converted = convert(jsonText, "json", format);
      if (converted.ok) {
        setAcceptedOpfText(converted.text);
        setOpfDraft(converted.text);
      } else {
        // Conversion failed — fall back to JSON so the user still has the doc.
        setAcceptedOpfText(jsonText);
        setOpfDraft(jsonText);
      }
    };

    if (activeOpf) {
      apply(activeOpf.opf);
      return;
    }
    if (thread) {
      setAcceptedOpfText("");
      setOpfDraft("");
    }
  }, [activeOpf?.id, activeOpf, thread?.id, thread, format, setOpfDraft]);

  useEffect(() => {
    if (runs.length === 0) {
      setSelectedRunId(null);
      return;
    }
    if (!selectedRunId || !runs.some((run) => run.id === selectedRunId)) {
      setSelectedRunId(runs[0].id);
    }
  }, [runs, selectedRunId]);

  useEffect(() => {
    const pendingRun = runs.find(
      (run) => run.status === "needs_review" && run.toolMeta?.proposal
    );
    if (!pendingRun?.toolMeta?.proposal) {
      setPendingGhostEdit(null);
      return;
    }
    const proposal = pendingRun.toolMeta.proposal;
    setPendingGhostEdit((current) => {
      if (current?.runId === pendingRun.id) return current;
      return {
        runId: pendingRun.id,
        operation: pendingRun.operation,
        proposedAt: proposal.createdAt ?? pendingRun.createdAt,
        hunks: proposal.hunks,
      };
    });
  }, [runs]);

  useEffect(() => {
    if (centerTab === "diff" && ghostHunkCount === 0) {
      setCenterTab("code");
    }
  }, [centerTab, ghostHunkCount]);

  useEffect(() => {
    const nextIndex = slideIndexFromPath(effectiveSelectedPath);
    if (nextIndex != null) {
      setSelectedPreviewSlideIndex(nextIndex);
      if (centerTab === "preview") setPreviewSelectionPath(effectiveSelectedPath);
    }
  }, [centerTab, effectiveSelectedPath]);

  useEffect(() => {
    const count = previewDocument?.slides.length ?? 0;
    if (count <= 0) {
      setSelectedPreviewSlideIndex(0);
      return;
    }
    setSelectedPreviewSlideIndex((current) => Math.min(Math.max(current, 0), count - 1));
  }, [previewDocument?.slides.length]);

  useEffect(() => {
    let cancelled = false;

    async function hydrateFromHandoff() {
      try {
        const handoff = await readOpfHandoffFromUrl(window.location.href);
        if (!handoff || cancelled) return;
        setHandoffOpf(buildHandoffOpfDocument(handoff.doc));
        setSnapshot(null);
        setSelectedRunId(null);
        setSelectedOpfDocumentId(null);
        setPrompt("");
        setRawText("");
        setAttachments([]);
        setInputMode("prompt");
        setOperationMode("auto");
        setSurfaceError(null);
      } catch (error) {
        if (!cancelled) {
          setSurfaceError(
            "Could not load the OPF handoff: " + (error instanceof Error ? error.message : String(error))
          );
        }
      }
    }

    hydrateFromHandoff();
    return () => {
      cancelled = true;
    };
  }, []);

  const jumpToPath = useCallback((path: string) => {
    editorJumpIdRef.current += 1;
    setEditorJumpTarget({ id: editorJumpIdRef.current, path });
  }, []);

  const handlePreviewSlideSelect = useCallback(
    (index: number) => {
      const path = `$.slides[${index}]`;
      setSelectedPreviewSlideIndex(index);
      setPreviewSelectionPath(path);
      jumpToPath(path);
    },
    [jumpToPath]
  );

  const handlePreviewPathSelect = useCallback(
    (path: string) => {
      const slideIndex = slideIndexFromPath(path);
      if (slideIndex != null) setSelectedPreviewSlideIndex(slideIndex);
      setPreviewSelectionPath(path);
      jumpToPath(path);
    },
    [jumpToPath]
  );

  const openLibraryLauncher = useCallback((kind: GalleryKind | "all" | "designs" = "all") => {
    setLibraryLauncher({ kind, open: true });
  }, []);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        openLibraryLauncher("all");
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [openLibraryLauncher]);

  useEffect(() => {
    if (activityTab === "agent") return;
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setActivityTab("agent");
    };
    window.addEventListener("keydown", handleEscape);
    return () => window.removeEventListener("keydown", handleEscape);
  }, [activityTab]);

  const handleFiles = useCallback(async (files: FileList | File[]) => {
    const incoming = Array.from(files);
    const accepted: Attachment[] = [];
    const rejected: string[] = [];
    const readErrors: string[] = [];

    for (const file of incoming) {
      if (isAcceptedUpload(file.name)) {
        let text: string | undefined;
        try {
          text = await readUploadText(file);
        } catch {
          readErrors.push(file.name);
        }

        accepted.push({
          id: `${file.name}-${file.lastModified}-${file.size}`,
          name: file.name,
          size: file.size,
          type: file.type || extensionLabel(file.name),
          text,
        });
      } else {
        rejected.push(file.name);
      }
    }

    if (accepted.length > 0) {
      setAttachments((current) => dedupeAttachments([...current, ...accepted]).slice(0, 5));
      setSurfaceError(null);
      setInputMode("upload");
      setOperationMode(thread ? "create" : "auto");
    }
    if (rejected.length > 0) {
      setSurfaceError(`Unsupported upload type: ${rejected.join(", ")}.`);
    } else if (readErrors.length > 0) {
      setSurfaceError(`Could not read source text from: ${readErrors.join(", ")}.`);
    }
  }, [thread]);

  const persistPromptAndRedirectToSignIn = useCallback(() => {
    if (!readCurrentDraft()) return;
    if (typeof window !== "undefined") {
      // Saves to sessionStorage so the typed prompt survives the Clerk sign-in
      // page reload; restored on mount by the effect below. Attachment file
      // contents aren't serializable so `hadAttachments` flags lost uploads
      // and the restore path warns + skips auto-submit when set.
      writeAuthorPendingSubmit(window.sessionStorage, {
        prompt,
        rawText,
        inputMode,
        hadAttachments: attachments.length > 0,
      });
    }
    redirectToSignIn();
  }, [attachments.length, inputMode, prompt, rawText, readCurrentDraft]);

  const fetchThreadSnapshot = useCallback(async (
    threadId: string,
    options: { redirectOnUnauthorized?: boolean } = {}
  ) => {
    const response = await fetch(`/api/v1/author/threads/${encodeURIComponent(threadId)}`);
    if (response.status === 401) {
      if (options.redirectOnUnauthorized !== false) redirectToSignIn();
      return null;
    }

    const body = (await response.json().catch(() => null)) as AuthorThreadSnapshot | ApiErrorBody | null;
    if (!response.ok || !isAuthorThreadSnapshot(body)) {
      throw new Error(errorMessageFromBody(body, "Could not load Author thread."));
    }

    return body;
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") {
      setHydrationSettled(true);
      return;
    }
    const threadId = threadIdFromAuthorUrl(window.location.href);
    if (!threadId) {
      setHydrationSettled(true);
      return;
    }
    if (!initialSignedIn) {
      setSurfaceError("Sign in to open saved Author threads. Continuing with your local browser draft.");
      setHydrationSettled(true);
      return;
    }
    const requestedThreadId = threadId;

    let cancelled = false;
    async function hydrateThread() {
      try {
        const loaded = await fetchThreadSnapshot(requestedThreadId, { redirectOnUnauthorized: false });
        if (!loaded || cancelled) {
          if (!cancelled && !loaded) {
            setSurfaceError("Could not open that saved Author thread. Continuing with your local browser draft.");
          }
          return;
        }
        setSnapshot(loaded);
        setHandoffOpf(null);
        setSelectedRunId(null);
        setSelectedOpfDocumentId(loaded.latestOpf?.id ?? null);
        setPrompt("");
        setRawText("");
        setAttachments([]);
        setInputMode("prompt");
        setOperationMode("auto");
        setSurfaceError(null);
      } catch (error) {
        if (!cancelled) {
          setSurfaceError(
            "Could not open that saved Author thread. Continuing with your local browser draft. " +
              (error instanceof Error ? error.message : String(error))
          );
        }
      } finally {
        if (!cancelled) setHydrationSettled(true);
      }
    }
    hydrateThread();
    return () => {
      cancelled = true;
    };
  }, [fetchThreadSnapshot, initialSignedIn]);

  // Drain any prompt the user typed before being bounced to Clerk sign-in into
  // component state, but don't apply it yet — the thread-hydration effect above
  // wipes the prompt on success, so we wait until hydration settles before
  // restoring (otherwise the restored text gets clobbered and, worse,
  // auto-submit could fire before `thread` is loaded and create a new thread).
  useEffect(() => {
    if (typeof window === "undefined") return;
    const result = readAuthorPendingSubmit(window.sessionStorage);
    clearAuthorPendingSubmit(window.sessionStorage);
    if (!result.ok || !result.pending) return;
    if (!hasAuthorPendingSubmitContent(result.pending)) return;
    setPendingRestore(result.pending);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Apply the restored intent once hydration is settled. Auto-submit only when
  // the page reloads back as signed in; otherwise just refill the composer so
  // they can resend or edit. If the user had attached files (which can't be
  // persisted to sessionStorage), drop them out of upload mode and warn rather
  // than silently auto-submitting without the file context they intended.
  useEffect(() => {
    if (!pendingRestore || !hydrationSettled) return;
    const intent = pendingRestore;
    setPendingRestore(null);
    setPrompt(intent.prompt);
    setRawText(intent.rawText);
    setInputMode(intent.hadAttachments ? "prompt" : intent.inputMode);
    if (intent.hadAttachments) {
      setSurfaceError(
        "Your uploaded files weren't preserved across sign-in. Re-attach them before sending."
      );
      return;
    }
    if (initialSignedIn) setAutoSubmitArmed(true);
  }, [hydrationSettled, initialSignedIn, pendingRestore]);

  // The Agent tab uses AI SDK `useChat` as the live transcript and Convex thread
  // snapshots as durable replay. Browser chat sends every prompt through the
  // AuthorAgent tool loop; snapshots are only rehydration after thread/run changes.
  const agentInitialMessages = useMemo<AuthorAgentMessage[]>(() => {
    const runById = new Map(runs.map((run) => [run.id, run]));
    return messages
      .map((message) =>
        authorMessageToUIMessage(
          message,
          message.runId ? runById.get(message.runId) : undefined
        ) as AuthorAgentMessage
      )
      .filter((message) => message.parts.length > 0);
  }, [messages, runs]);
  const agentMessagesSyncKey = useMemo(
    () => authorMessagesSyncKey(messages, runs),
    [messages, runs]
  );
  const agentOperation: AuthorConversationOperation =
    operationMode === "create" || operationMode === "ask"
      ? operationMode
      : thread?.latestOpfDocumentId
        ? "refine"
        : "create";
  const agentTransport = useMemo(
    () =>
      new DefaultChatTransport<AuthorAgentMessage>({
        api: threadId ? `/api/v1/author/threads/${threadId}/messages` : "/api/v1/author/threads",
        body: {
          operation: agentOperation,
          context: {
            selectionPath: effectiveSelectedPath,
            pinnedPaths,
          },
        },
      }),
    [agentOperation, effectiveSelectedPath, pinnedPaths, threadId]
  );
  const handleAgentFinish = useCallback(async () => {
    if (!threadId) return;
    const loaded = await fetchThreadSnapshot(threadId);
    if (loaded) setSnapshot(loaded);
  }, [fetchThreadSnapshot, threadId]);
  const agentChat = useChat<AuthorAgentMessage>({
    id: threadId ? `author-thread-${threadId}` : "author-local",
    messages: agentInitialMessages,
    transport: agentTransport,
    sendAutomaticallyWhen: lastAssistantMessageIsCompleteWithApprovalResponses,
    onFinish: handleAgentFinish,
    onError: (error) => {
      setSurfaceError(error.message);
      void handleAgentFinish();
    },
  });
  useEffect(() => {
    if (!threadId || !pendingInitialAgentMessage) return;
    if (canvasRef.current && !canvasRef.current.commit()) return;
    const pending = pendingInitialAgentMessage;
    setPendingInitialAgentMessage(null);
    setIsSending(true);
    void agentChat
      .sendMessage(
        { text: pending.text },
        {
          body: {
            operation: "create",
            context: pending.context,
          },
        }
      )
      .then(() => {
        setPrompt("");
        setRawText("");
        setAttachments([]);
        setInputMode("prompt");
        setOperationMode("auto");
      })
      .catch((error) => {
        setSurfaceError(error instanceof Error ? error.message : String(error));
      })
      .finally(() => {
        setIsSending(false);
      });
  }, [agentChat, pendingInitialAgentMessage, threadId]);
  const handleAgentToolApprovalResponse = useCallback(
    async (response: {
      id: string;
      approved: boolean;
      reason?: string;
    }) => {
      await agentChat.addToolApprovalResponse({
        ...response,
        options: {
          body: {
            operation: "refine",
            context: {
              selectionPath: effectiveSelectedPath,
              pinnedPaths,
            },
          },
        },
      });
      if (!response.approved) return;
      for (const delayMs of [1500, 4000, 9000]) {
        window.setTimeout(() => {
          void handleAgentFinish();
        }, delayMs);
      }
    },
    [agentChat, effectiveSelectedPath, handleAgentFinish, pinnedPaths]
  );
  const syncedAgentMessagesKeyRef = useRef<string | null>(null);
  const { setMessages: setAgentMessages } = agentChat;
  useEffect(() => {
    if (syncedAgentMessagesKeyRef.current === agentMessagesSyncKey) return;
    syncedAgentMessagesKeyRef.current = agentMessagesSyncKey;
    setAgentMessages(agentInitialMessages);
  }, [agentInitialMessages, agentMessagesSyncKey, setAgentMessages]);

  const applyLocalAuthorMetadata = useCallback(
    (author: string) => {
      const draft = readCurrentDraft();
      if (!draft?.document) return false;
      const nextDocument = structuredClone(draft.document);
      nextDocument.author = author;
      const jsonText = toJsonText(nextDocument);
      let nextText = jsonText;
      if (format !== "json") {
        const converted = convert(jsonText, "json", format);
        if (!converted.ok) {
          setSurfaceError(`Could not update ${format.toUpperCase()} draft: ${converted.error}`);
          return false;
        }
        nextText = converted.text;
      }

      setOpfDraft(nextText);
      setPrompt("");
      setSurfaceError(null);
      jumpToPath("$.author");
      return true;
    },
    [format, jumpToPath, readCurrentDraft, setOpfDraft]
  );

  const applyLocalRawOpf = useCallback((textOverride?: string) => {
    const text = (textOverride ?? rawText).trim();
    if (!text) {
      setSurfaceError("Paste OPF JSON before importing locally.");
      return false;
    }
    const parsed = parseDocument(text, "json");
    if (!parsed.document) {
      setSurfaceError(
        parsed.error
          ? `Could not import OPF JSON: ${parsed.error}`
          : "Could not import OPF JSON."
      );
      return false;
    }

    const jsonText = toJsonText(parsed.document);
    const nextVersion = Math.max(0, ...localVersions.map((version) => version.version)) + 1;
    const now = new Date().toISOString();
    setSnapshot(null);
    setHandoffOpf(null);
    setSelectedRunId(null);
    setSelectedOpfDocumentId(null);
    setAcceptedOpfText(jsonText);
    setOpfDraft(jsonText);
    setFormat("json");
    setRawText("");
    setPrompt("");
    setAttachments([]);
    setInputMode("prompt");
    setOperationMode("auto");
    setLocalVersions((current) =>
      trimAuthorLocalVersions([
        createAuthorLocalVersion({
          acceptedOpfText: jsonText,
          createdAt: now,
          format: "json",
          label: "Imported OPF",
          opfDraft: jsonText,
          version: nextVersion,
        }),
        ...current,
      ])
    );
    setSurfaceError(null);
    return true;
  }, [localVersions, rawText, setFormat, setOpfDraft]);

  const handleSubmit = useCallback(async () => {
    if (!readCurrentDraft()) return;
    setSurfaceError(null);
    setCopiedPayload(false);
    setCopiedJson(false);

    if (localAuthorMetadataIntent) {
      if (localAuthorMetadataIntent.kind === "needs_author_name") {
        setSurfaceError("What name should I set as the author?");
        return;
      }
      applyLocalAuthorMetadata(localAuthorMetadataIntent.value);
      return;
    }

    if (!thread && !initialSignedIn) {
      const trimmed = prompt.trim();
      if (inputMode === "raw" || (trimmed.startsWith("{") && trimmed.endsWith("}"))) {
        applyLocalRawOpf(trimmed || undefined);
        return;
      }
      setSurfaceError("Sign in to create or refine decks with Author AI. You can still edit, import OPF JSON, use galleries, and export locally.");
      return;
    }

    if (viewingHistoricalVersion && latestOpf) {
      const latestText = opfTextForFormat(latestOpf.opf, format);
      setSelectedOpfDocumentId(latestOpf.id);
      setAcceptedOpfText(latestText);
      setOpfDraft(latestText);
    }

    const agentMessage =
      inputMode === "raw"
        ? null
        : prepareAgentMessageText({ attachments, inputMode, prompt });
    if (agentMessage && !agentMessage.ok) {
      setSurfaceError(agentMessage.error);
      return;
    }

    if (agentMessage?.ok) {
      const context = authorAgentRequestContext({
        pinnedPaths,
        selectionPath: selectedPath && selectedPath !== "$" ? selectedPath : null,
      });

      if (!thread) {
        let handedOffToAgent = false;
        setIsSending(true);
        try {
          const response = await fetch("/api/v1/author/threads", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              client: { surface: "author-playground", chat: "agent-loop" },
            }),
          });
          if (response.status === 401) {
            persistPromptAndRedirectToSignIn();
            return;
          }
          const body = (await response.json().catch(() => null)) as
            | AuthorThreadSnapshot
            | ApiErrorBody
            | null;
          if (!response.ok || !isAuthorThreadSnapshot(body)) {
            throw new Error(errorMessageFromBody(body, "Could not create Author thread."));
          }

          setSnapshot(body);
          setHandoffOpf(null);
          setSelectedRunId(null);
          setSelectedOpfDocumentId(body.latestOpf?.id ?? null);
          setPendingInitialAgentMessage({ text: agentMessage.text, context });
          if (typeof window !== "undefined") {
            window.history.replaceState(
              null,
              "",
              `/author?thread=${encodeURIComponent(body.thread.id)}`
            );
          }
          handedOffToAgent = true;
        } catch (error) {
          setSurfaceError(error instanceof Error ? error.message : String(error));
        } finally {
          if (!handedOffToAgent) setIsSending(false);
        }
        return;
      }

      setIsSending(true);
      try {
        await agentChat.sendMessage(
          { text: agentMessage.text },
          {
            body: {
              operation: agentOperation,
              context,
            },
          }
        );
        setPrompt("");
        setRawText("");
        setAttachments([]);
        setInputMode("prompt");
        setOperationMode("auto");
      } catch (error) {
        setSurfaceError(error instanceof Error ? error.message : String(error));
      } finally {
        setIsSending(false);
      }
      return;
    }

    if (!payloadPreview.ok) {
      setSurfaceError(payloadPreview.error);
      return;
    }

    setIsSending(true);
    try {
      const response = await fetch(payloadPreview.payload.endpoint, {
        method: payloadPreview.payload.method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payloadPreview.payload.body),
      });
      if (response.status === 401) {
        persistPromptAndRedirectToSignIn();
        return;
      }

      const body = (await response.json().catch(() => null)) as
        | AuthorThreadSnapshot
        | AuthorConversationResult
        | ApiErrorBody
        | null;
      if (!response.ok) {
        throw new Error(errorMessageFromBody(body, "Author request failed."));
      }

      if (!thread) {
        if (!isAuthorThreadSnapshot(body)) {
          throw new Error("Author thread creation returned an unexpected response.");
        }
        setSnapshot(body);
        setHandoffOpf(null);
        setPrompt("");
        setRawText("");
        setAttachments([]);
        setInputMode("prompt");
        setOperationMode("auto");
        setSelectedRunId(body.result?.runId ?? null);
        setSelectedOpfDocumentId(body.latestOpf?.id ?? null);
        if (typeof window !== "undefined") {
          window.history.replaceState(
            null,
            "",
            `/author?thread=${encodeURIComponent(body.thread.id)}`
          );
        }
        return;
      }

      if (!isAuthorConversationResult(body)) {
        throw new Error("Author message returned an unexpected response.");
      }

      const loaded = await fetchThreadSnapshot(body.threadId);
      if (loaded) {
        setSnapshot(loaded);
        setHandoffOpf(null);
        setPrompt("");
        setRawText("");
        setAttachments([]);
        setInputMode("prompt");
        setOperationMode("auto");
        setSelectedRunId(body.runId);
      }
    } catch (error) {
      setSurfaceError(error instanceof Error ? error.message : String(error));
    } finally {
      setIsSending(false);
    }
  }, [
    applyLocalAuthorMetadata,
    applyLocalRawOpf,
    fetchThreadSnapshot,
    format,
    initialSignedIn,
    inputMode,
    latestOpf,
    localAuthorMetadataIntent,
    payloadPreview,
    persistPromptAndRedirectToSignIn,
    prompt,
    agentChat,
    agentOperation,
    attachments,
    pinnedPaths,
    selectedPath,
    thread,
    viewingHistoricalVersion,
