  const handleFilenameCommit = useCallback(
    (value: string) => {
      if (isSending) return false;
      if (!parseState.document) {
        setSurfaceError("Create a deck before editing the filename.");
        return false;
      }

      const filename = normalizeAuthorFilenameInput(value);
      if (!filename.ok) {
        setSurfaceError(filename.errors[0] ?? "Filename is not valid.");
        return false;
      }

      const nextDocument = JSON.parse(JSON.stringify(parseState.document)) as OPFDocument;
      if (filename.value) {
        nextDocument.filename = filename.value;
      } else {
        delete nextDocument.filename;
      }

      const jsonText = toJsonText(nextDocument);
      let nextText = jsonText;
      if (format !== "json") {
        const converted = convert(jsonText, "json", format);
        if (!converted.ok) {
          setSurfaceError(`Could not update ${format.toUpperCase()} draft: ${converted.error}`);
          return false;
        }
        nextText = converted.text;
      }

      const draftWasClean = acceptedOpfText === opfDraft;
      setOpfDraft(nextText);
      if (draftWasClean) setAcceptedOpfText(nextText);
      setSurfaceError(null);
      return true;
    },
    [acceptedOpfText, format, isSending, opfDraft, parseState.document, setOpfDraft]
  );

