  // Refresh post-run follow-up chips when the latest applied run changes.
  // Uses the backend endpoint, which prefers the AI path and falls back
  // to deterministic if AI is disabled or fails.
  //
  // `authorIntent` is intentionally NOT in the deps array: it changes on
  // every keystroke, which would cancel and re-skip the fetch (the run-id
  // dedup guards against re-firing for the same applied run). The intent
  // is read through a ref so the in-flight fetch sees the latest value
  // but typing mid-fetch doesn't void the request.
  //
  // Out-of-order safety: we don't use a `cancelled` flag because the
  // cleanup would otherwise strand `followUpLoading=true` whenever the
  // effect re-runs and bails at the dedup check. Instead the async block
  // gates state writes on `followUpRunRef.current === runIdAtFetchTime`,
  // so a late-arriving response for a superseded run is dropped while a
  // mid-flight fetch for the *same* run still completes correctly.
  const authorIntentRef = useRef(authorIntent);
  useEffect(() => {
    authorIntentRef.current = authorIntent;
  }, [authorIntent]);

  useEffect(() => {
    const applied = runs.find((run) => run.status === "applied");
    if (!applied) {
      setFollowUpChips([]);
      setFollowUpLoading(false);
      followUpRunRef.current = null;
      return;
    }
    if (!parseDraftState.document) {
      // OPF is mid-edit (invalid JSON). Don't clear the dedup ref or the
      // chips — typing past a parse error and back would otherwise reset
      // the guard and re-fire the fetch for the same applied run.
      return;
    }
    if (followUpRunRef.current === applied.id) {
      // Already fetched (or fetching) chips for this run. Don't touch
      // `followUpLoading` — the original fetch's `finally` clears it via
      // the run-id gate. Resetting it here while the fetch is still in
      // flight would create a brief gap where neither the loading
      // indicator nor the chips are visible.
      return;
    }
    followUpRunRef.current = applied.id;
    const runIdAtFetchTime = applied.id;
    const opfForChips = parseDraftState.document;
    setFollowUpLoading(true);

    void (async () => {
      try {
        const response = await fetch("/api/v1/author/follow-ups", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            intent: authorIntentRef.current,
            opf: opfForChips,
            lastAssistantText: applied.assistantText,
            lastOperation: applied.operation,
          }),
        });
        if (!response.ok) throw new Error(`follow-ups ${response.status}`);
        const payload = (await response.json()) as { chips?: FollowUpChip[] };
        if (followUpRunRef.current === runIdAtFetchTime && Array.isArray(payload.chips)) {
          setFollowUpChips(payload.chips);
        }
      } catch {
        if (followUpRunRef.current === runIdAtFetchTime) {
          setFollowUpChips(
            deterministicFollowUps({
              intent: authorIntentRef.current,
              opf: opfForChips,
              lastAssistantText: applied.assistantText,
              lastOperation: applied.operation as "create" | "refine" | "ask",
            })
          );
        }
      } finally {
        if (followUpRunRef.current === runIdAtFetchTime) {
          setFollowUpLoading(false);
        }
      }
    })();
    // authorIntent is intentionally read via `authorIntentRef.current`
    // (see the comment block above for why). Because the ref itself is
    // stable, `react-hooks/exhaustive-deps` does not flag the omission,
    // so no eslint-disable is necessary here — the deps list is complete.
  }, [runs, parseDraftState.document]);

  const handleFollowUpPick = useCallback(
    (chip: FollowUpChip) => {
      setPrompt(chip.prompt);
      setInputMode("prompt");
    },
    []
  );

  const togglePin = useCallback(() => {
    if (!effectiveSelectedPath) return;
    setPinnedPaths((current) =>
      current.includes(effectiveSelectedPath)
        ? current.filter((p) => p !== effectiveSelectedPath)
        : [...current, effectiveSelectedPath].slice(-4)
    );
  }, [effectiveSelectedPath]);

  const commitDraftDocument = useCallback(
    (nextDocument: OPFDocument, path?: string) => {
      const nextValidation = validateOPF(nextDocument);
      if (!nextValidation.valid) {
        setSurfaceError(nextValidation.errors[0]?.message ?? "Update produced invalid OPF.");
        return false;
      }
      const jsonText = toJsonText(nextDocument);
      if (format === "json") {
        setOpfDraft(jsonText);
      } else {
        const converted = convert(jsonText, "json", format);
        if (!converted.ok) {
          setSurfaceError(`Could not update ${format.toUpperCase()} draft: ${converted.error}`);
          return false;
        }
        setOpfDraft(converted.text);
      }
      setSurfaceError(null);
      if (path) jumpToPath(path);
      return true;
    },
    [format, jumpToPath, setOpfDraft]
  );

  const handleSchemaValueApply = useCallback(
    (path: string, value: unknown) => {
      const baseDocument = parseState.document;
      if (!baseDocument || isSending) return;
      const nextDocument = JSON.parse(JSON.stringify(baseDocument)) as OPFDocument;
      if (!setValueAtOpfPath(nextDocument, path, value)) {
        setSurfaceError(`Could not update ${path}.`);
        return;
      }
      commitDraftDocument(nextDocument, path);
    },
    [commitDraftDocument, isSending, parseState.document]
  );

  // Preflight raw source before the semantic session consumes an undo step.
  // The one-shot token acknowledges only this exact synchronous patch callback.
  const commitPresetDocument = useCallback((draft: AuthorDraft, nextDocument: OPFDocument, rawResult?: AuthorSource) => {
    let pending: PresetTransaction | null = null;
    try {
      const editor = canvasSession.editor;
      if (isSending || !editor || readySessionRef.current !== editor || presetTransactionRef.current
        || sourceRef.current.text !== draft.text || sourceRef.current.format !== draft.format
        || !sameJsonValue(editor.document, draft.document)) {
        throw new Error("The draft changed before this preset edit could be applied. Reopen the current draft and try again.");
      }
      for (const document of [draft.document, nextDocument]) {
        const checked = validateOPF(document);
        if (!checked.valid) throw new Error(checked.errors[0]?.message ?? "Preset edit requires valid OPF.");
      }
      if (sameJsonValue(draft.document, nextDocument)
        && (!rawResult || (rawResult.text === draft.text && rawResult.format === draft.format))) {
        return { changed: false, editor, source: { text: draft.text, format: draft.format }, snapshot: editor.snapshot() };
      }
      let result: AuthorSource;
      if (rawResult) {
        if (rawResult.format !== draft.format) throw new Error("The source format changed after these presets were applied.");
        result = { ...rawResult };
        if (draft.format === "json") {
          updateJsonSource(draft.text, draft.document);
          updateJsonSource(result.text, nextDocument);
        }
      } else if (draft.format === "json") {
        result = { text: updateJsonSource(draft.text, nextDocument), format: draft.format };
      } else {
        const converted = convert(toJsonText(nextDocument), "json", draft.format);
        if (!converted.ok) throw new Error(converted.error);
        result = { text: converted.text, format: draft.format };
      }
      const parsed = parseText(result.text, result.format);
      if (!parsed.ok || !sameJsonValue(parsed.doc, nextDocument)) {
        throw new Error("This preset edit cannot be represented in the current source format. Your source was kept.");
      }
      const expected = { text: draft.text, format: draft.format };
      pending = {
        token: {}, editor, before: draft.document, after: nextDocument, expected, result,
        undoDepth: editor.snapshot().undoDepth + 1,
        override: rawResult ? { expected, result } : undefined,
        accepted: false,
      };
      const rejectedBeforeCommit = rejectedCanvasChangeRef.current;
      presetTransactionRef.current = pending;
      editor.applyPatch([{ op: "replace", path: "", value: nextDocument }], {
        source: "author-preset", authorPresetTransaction: pending.token, rejectInvalid: true,
      });
      if (!pending.accepted || rejectedCanvasChangeRef.current !== rejectedBeforeCommit
        || readySessionRef.current !== editor
        || sourceRef.current.text !== result.text || sourceRef.current.format !== result.format
        || !sameJsonValue(editor.document, nextDocument)) {
        throw new Error("The preset edit was not accepted by the current draft. Your source was kept.");
      }
      setSurfaceError(null);
      return { changed: true, editor, source: result, snapshot: editor.snapshot() };
    } catch (error) {
      invalidatePresetGroup();
      setSurfaceError(error instanceof Error ? error.message : "Could not apply the preset edit.");
      return null;
    } finally {
      if (presetTransactionRef.current === pending) presetTransactionRef.current = null;
    }
  }, [canvasSession.editor, invalidatePresetGroup, isSending]);

  const handlePresetApply = useCallback(
    (suggestion: PresetSuggestion) => {
      if (isSending) return;
      // An inline draft is committed before taking the group's initial source.
      const current = readCurrentDraft();
      if (!current?.document) return;
      const draft: AuthorDraft = { ...current, document: current.document };
      const previousGroup = presetGroupRef.current;
      const group = previousGroup && matchesPresetGroup(previousGroup, draft, canvasSession.editor) ? previousGroup : null;
      if (previousGroup && !group) invalidatePresetGroup();
      const applied = applyPresetToOpf(draft.document, suggestion);
      if (!applied) {
        setSurfaceError(`Could not apply ${suggestion.label} — field is not deck-wide.`);
        return;
      }
      const committed = commitPresetDocument(draft, applied.nextOpf);
      if (!committed?.changed) return;
      presetGroupRef.current = {
        editor: committed.editor,
        original: group?.original ?? { text: draft.text, format: draft.format },
        expected: committed.source,
        undoDepth: committed.snapshot.undoDepth,
        redoDepth: committed.snapshot.redoDepth,
      };
      const toastId = `preset-${suggestion.kind}-${suggestion.id}-${Date.now().toString(36)}`;
      setPresetToasts((toasts) => [
        ...toasts,
        { id: toastId, fieldPath: applied.fieldPath, label: suggestion.label, before: applied.previousValue, after: applied.nextValue },
      ]);
      jumpToPath(applied.fieldPath);
    },
    [canvasSession.editor, commitPresetDocument, invalidatePresetGroup, isSending, jumpToPath, readCurrentDraft]
  );

  const handlePresetUndoAll = useCallback(() => {
    if (isSending || !presetGroupRef.current) return;
    const requestedGroup = presetGroupRef.current;
    const current = readCurrentDraft();
    if (!current?.document) return;
    // Committing a newer inline edit can invalidate the group synchronously.
    const group = presetGroupRef.current;
    if (!group || group !== requestedGroup || !matchesPresetGroup(group, current, canvasSession.editor)) {
      invalidatePresetGroup();
      setSurfaceError("The draft changed after these presets were applied. Your newer edits were kept.");
      return;
    }
    const original = parseDocument(group.original.text, group.original.format);
    if (!original.document) {
      invalidatePresetGroup();
      setSurfaceError("The original preset source is no longer valid. Your current draft was kept.");
      return;
    }
    const committed = commitPresetDocument({ ...current, document: current.document }, original.document, group.original);
    if (committed) invalidatePresetGroup();
  }, [canvasSession.editor, commitPresetDocument, invalidatePresetGroup, isSending, readCurrentDraft]);

  const handleGalleryApply = useCallback(
    async (path: string, item: GalleryItem) => {
      const baseDocument = readCurrentDraft()?.document;
      if (isSending || !baseDocument) return;
      const value = galleryPatchValueForPath(path, item);

      const applyLocally = () => {
        const applied = applyGalleryItemToDocument(baseDocument, path, item);
        if (!applied) {
          setSurfaceError(`Could not apply ${item.id} to ${path}.`);
          return;
        }
        commitDraftDocument(applied.document, path);
      };

      if (!thread?.id || !thread.latestOpfDocumentId) {
        applyLocally();
        return;
      }

      setSurfaceError(null);
      setIsSending(true);
      try {
        const contextPinnedPaths = [...pinnedPaths.filter((p) => p !== path), path].slice(-4);
        await agentChat.sendMessage(
          { text: `Set ${path} to ${JSON.stringify(value)}.` },
          {
            body: {
              operation: "refine",
              context: {
                selectionPath: path,
                pinnedPaths: contextPinnedPaths,
              },
            },
          }
        );
        const loaded = await fetchThreadSnapshot(thread.id);
        if (loaded) {
          setSnapshot(loaded);
          setHandoffOpf(null);
          setSelectedRunId(sortRuns(loaded.runs)[0]?.id ?? null);
          jumpToPath(path);
        }
      } catch (error) {
        setSurfaceError(error instanceof Error ? error.message : String(error));
      } finally {
        setIsSending(false);
      }
    },
    [
      agentChat,
      fetchThreadSnapshot,
      commitDraftDocument,
      isSending,
      jumpToPath,
      parseState.document,
      pinnedPaths,
      thread?.id,
      thread?.latestOpfDocumentId,
      readCurrentDraft,
    ]
  );

  const handleLibrarySourceAdd = useCallback(async (url: string) => {
    try {
      const source = await fetchAuthorGallerySourceFromUrl({ url });
      setLocalGallerySources((current) => [
        source,
        ...current.filter((item) => item.id !== source.id),
      ].slice(0, 20));
    } catch (error) {
      setSurfaceError(error instanceof Error ? error.message : String(error));
    }
  }, []);

  const handleLibraryDefault = useCallback((item: GalleryItem) => {
    setSurfaceError(`Default preferences UI is not connected yet for ${item.id}.`);
  }, []);

  const validationIssues: ValidationIssue[] = useMemo(() => {
    if (!validation) return [];
    const errors = validation.errors.map<ValidationIssue>((e) => ({
      path: e.path,
      message: e.message,
      severity: "error",
    }));
    const warnings = validation.warnings.map<ValidationIssue>((w) => ({
      path: w.path,
      message: w.message,
      severity: "warning",
    }));
    return [...errors, ...warnings];
  }, [validation]);
  const versionLabel = activeOpf ? `v${activeOpf.version}` : null;
  const currentOpfDocumentId =
    activeOpf && thread && activeOpf.threadId === thread.id ? activeOpf.id : null;
  const slideCount = deckSummary.slideCount ?? 0;
  const activeVersionLabel =
    authorStorageMode === "remote" ? versionLabel ?? (parseState.document ? "v1" : null) : null;
  const showCenterModeToggle = centerTab === "code" || centerTab === "preview";
  const activityTabs = [
    {
      id: "agent" as const,
      label: "agent",
      icon: <Bot className="size-3" aria-hidden />,
    },
    {
      id: "tools" as const,
      label: "tools",
      count: toolCalls.length > 0 ? toolCalls.length : undefined,
      icon: <Wrench className="size-3" aria-hidden />,
    },
    {
      id: "schema" as const,
      label: "schema",
      icon: <Braces className="size-3" aria-hidden />,
    },
  ];

  return (
    <div className="flex h-full min-h-0 w-full flex-col bg-background text-foreground">
      <AuthorWorkspaceStrip
        copiedJson={copiedJson}
        copiedShare={copiedShare}
        copiedThreadId={copiedThreadId}
        currentOpfDocumentId={currentOpfDocumentId}
        chrome={
          <AuthorHeaderChrome
            validity={validity}
            slideCount={slideCount}
            warningCount={validation?.warnings.length ?? 0}
            errorCount={errorCount}
            lastRun={lastRunSummary}
          />
        }
        filename={outputFilenameBase}
        filenameEditable={Boolean(parseState.document && !isSending)}
        latestOpfDocumentId={thread?.latestOpfDocumentId ?? null}
        onCommitFilename={handleFilenameCommit}
        onCopyJson={canPublishOutput ? handleCopyJson : undefined}
        onCopyThreadId={thread?.id ? handleCopyDocumentId : undefined}
        onExportJson={canPublishOutput ? () => handleDownloadTextExport("json") : undefined}
        onExportMarkdown={
          canPublishOutput ? () => handleDownloadTextExport("markdown") : undefined
        }
        onExportPptx={canPublishOutput ? handleExportPptx : undefined}
        onExportYaml={canPublishOutput ? () => handleDownloadTextExport("yaml") : undefined}
        onNewThread={handleNewThread}
        onSaveLocalToAccount={
          initialSignedIn && authorStorageMode === "local" && canPublishOutput
            ? handleSaveLocalToAccount
            : undefined
        }
        onShare={thread?.id ? handleShareWorkspace : undefined}
        pptxBusy={busyExport}
        pptxEnabled={canPublishOutput}
        saveLocalBusy={busySaveLocal}
        signedIn={initialSignedIn}
        storageMode={authorStorageMode}
        threadId={thread?.id ?? null}
        versionLabel={activeVersionLabel}
        versions={opfVersions}
        onSelectVersion={handleSelectOpfVersion}
        overflowMenu={
          <AuthorOverflowMenu
            documentId={thread?.id}
            onShareLink={thread?.id ? handleShareWorkspace : undefined}
            documentActions={[
              {
                kind: "action",
                label: thread ? "Duplicate as new thread" : "Reset local draft",
                onSelect: handleNewThread,
              },
            ]}
          />
        }
      />

      {exportNotes ? <div role="status" className="shrink-0 border-b border-border bg-muted/30 px-4 py-2 text-xs">
        <div className="flex items-center justify-between gap-3"><p>PowerPoint exported locally. Fonts and unsupported features may differ in PowerPoint; keep your OPF source.</p><button type="button" onClick={() => setExportNotes(null)} aria-label="Dismiss export notes">Dismiss</button></div>
        {exportNotes.length ? <details><summary>Conversion notes ({exportNotes.length})</summary><ul>{exportNotes.map(note => <li key={note}>{note}</li>)}</ul></details> : null}
      </div> : null}
      <main
        className={cn(
          "flex min-h-0 flex-1 flex-col overflow-y-auto lg:gap-0 lg:[grid-auto-rows:minmax(0,1fr)]",
          lgLayout
            ? cn(
                "lg:grid lg:overflow-hidden",
                !usePersistedWidths &&
                  "lg:[grid-template-columns:20rem_6px_minmax(0,1fr)_6px_24rem] 2xl:[grid-template-columns:20rem_6px_minmax(0,1fr)_6px_28rem]"
              )
            : null
        )}
        style={
          lgLayout && usePersistedWidths
            ? {
                gridTemplateColumns: `${leftRem}rem 6px minmax(0, 1fr) 6px ${rightRem}rem`,
              }
            : undefined
        }
      >
        <section className="order-1 flex min-h-[28rem] flex-col border-b border-border/50 bg-background lg:order-none lg:min-h-0 lg:overflow-hidden lg:border-r">
          <ActivityTabs
            tabs={activityTabs}
            value={activityTab}
            onChange={setActivityTab}
          />
          {activityTab === "agent" ? (
            <TranscriptPane
              messages={messages}
              uiMessages={agentChat.messages as AuthorUIMessage[]}
              runs={runs}
              onJumpToPath={jumpToPath}
              pendingGhostEdit={pendingGhostEdit}
              onGhostAcceptAll={handleGhostAcceptAll}
              onGhostRejectAll={handleGhostRejectAll}
              onGhostAcceptHunk={handleGhostAcceptHunk}
              onGhostRejectHunk={handleGhostRejectHunk}
              onGhostJump={handleGhostJump}
              onOpenDiff={() => setCenterTab("diff")}
              onToolApprovalResponse={handleAgentToolApprovalResponse}
              presetToasts={presetToasts}
              onPresetUndoAll={handlePresetUndoAll}
              followUpChips={followUpChips}
              followUpLoading={followUpLoading}
              onFollowUpPick={handleFollowUpPick}
            />
          ) : activityTab === "tools" ? (
            <AuthorToolsPane
              catalog={toolCatalog}
              onJumpToPath={jumpToPath}
              onSelectTool={setSelectedToolName}
              selectedToolName={selectedToolName}
              toolCalls={toolCalls}
            />
          ) : (
            <SchemaAccordionSidebar
              document={parseState.document}
              selectedPath={effectiveSelectedPath ?? "$"}
              validation={validation}
              onSelectPath={(path) => {
                jumpToPath(path);
              }}
              variant="embedded"
            />
          )}
          <LeftRailActionDock>
          {activityTab === "agent" ? (
              <AgentActionDock
                attachments={attachments}
                centerTab={centerTab}
                fileInputRef={fileInputRef}
                isSending={isSending || agentChat.status === "submitted" || agentChat.status === "streaming"}
                chatStatus={agentChat.status}
                onStop={agentChat.stop}
                onDropFiles={handleFiles}
                onFileInputChange={(event) => {
                  if (event.target.files) handleFiles(event.target.files);
                  event.target.value = "";
                }}
                onOperationModeChange={setOperationMode}
                onPromptChange={setPrompt}
                onRemoveAttachment={(id) =>
                  setAttachments((current) => current.filter((attachment) => attachment.id !== id))
                }
                onSample={handleSamplePrompt}
                onSignIn={persistPromptAndRedirectToSignIn}
                onSubmit={handleSubmit}
                operationMode={operationMode}
                prompt={prompt}
                previewSlideContext={previewSlideContext}
                localFieldUpdateActive={localAuthorMetadataIntent?.kind === "set_author"}
                signedIn={initialSignedIn}
                thread={thread}
                cursorPath={effectiveSelectedPath}
                pinnedPaths={pinnedPaths}
                onUnpinPath={(path) =>
                  setPinnedPaths((current) => current.filter((p) => p !== path))
                }
                chipSuggestions={agentChipSuggestions}
                hasMessages={messages.length > 0}
                intent={authorIntent}
                presetMatches={presetMatches}
                onPresetApply={handlePresetApply}
              />
            ) : activityTab === "tools" ? (
              <ToolsActionDock
                attachments={attachments}
              catalog={toolCatalog}
              document={parseState.document}
              gallerySources={effectiveGallerySources}
                manualOutput={manualToolOutput}
                onManualOutput={setManualToolOutput}
                onRecordToolCall={(call) =>
                  setManualToolCalls((current) => [call, ...current].slice(0, 20))
                }
                onSelectTool={setSelectedToolName}
                selectedPath={effectiveSelectedPath ?? null}
                selectedToolName={selectedToolName}
              />
            ) : null}
          </LeftRailActionDock>
        </section>

        <AuthorSplitHandle
          ariaLabel="Resize Agent and Edit panes"
          disabled={!lgLayout}
          onResize={(delta) => commit(leftRem + delta, rightRem)}
        />

        <section className="order-3 flex min-h-[36rem] flex-col bg-background lg:order-none lg:min-h-0 lg:overflow-hidden">
          <CenterTabs
            tabs={[
              { id: "code", label: "code" },
              { id: "preview", label: "preview", count: slideCount },
              ...(ghostHunkCount > 0
                ? [{ id: "diff" as const, label: "diff", count: ghostHunkCount }]
                : []),
            ]}
            value={centerTab}
            onChange={next => { if (!canvasRef.current || canvasRef.current.commit()) setCenterTab(next); }}
            trailing={
              showCenterModeToggle || ghostHunkCount > 0 ? (
                <>
                  {centerTab === "code" ? (
                    <FormatToggle format={format} onFormatChange={handleFormatChange} />
                  ) : centerTab === "preview" ? (
                    <PreviewExportToggle />
                  ) : null}
                {ghostHunkCount > 0 ? (
                  <>
                    {showCenterModeToggle ? (
                      <span aria-hidden className="text-muted-foreground/50">·</span>
                    ) : null}
                    <span className="inline-flex items-center gap-1 rounded-md bg-amber-500/15 px-1.5 py-0.5 font-mono text-amber-200">
                      {ghostHunkCount} pending edit{ghostHunkCount === 1 ? "" : "s"}
                    </span>
                  </>
                ) : null}
                </>
              ) : null
            }
          />
          <div className="flex min-h-0 flex-1 flex-col">
            {centerTab === "code" && pendingGhostEdit ? (
              <GhostEditBanner
                edit={pendingGhostEdit}
                onOpenDiff={() => setCenterTab("diff")}
              />
            ) : null}
            {centerTab === "code" ? (
              <AuthorEditPane
                catalogs={jsonFieldCatalogs}
                dirty={dirtyOpfDraft}
                isSending={isSending}
                jumpTarget={editorJumpTarget}
                cursor={
                  cursorSelection
                    ? {
                        line: cursorSelection.cursorLineNumber,
                        column: cursorSelection.cursorColumn,
                      }
                    : null
                }
                onCursorSelectionChange={setCursorSelection}
                format={format}
                onJumpError={setSurfaceError}
                onRevert={handleRevertOpfDraft}
                onOpfDraftChange={handleOpfDraftChange}
                opfDraft={opfDraft}
              />
            ) : centerTab === "preview" ? (
              <AuthorPreviewStack
                isSending={isSending}
                canvasSession={canvasSession}
                canvasRef={canvasRef}
                onJump={jumpToPath}
                parseError={parseState.error}
                previewSource={previewState}
                validation={validation}
              />
            ) : (
              <DiffTab
                edit={pendingGhostEdit}
                onAcceptAll={handleGhostAcceptAll}
                onAcceptHunk={handleGhostAcceptHunk}
                onRejectAll={handleGhostRejectAll}
                onRejectHunk={handleGhostRejectHunk}
              />
            )}
          </div>
        </section>

        <AuthorSplitHandle
          ariaLabel="Resize Edit and right rail"
          disabled={!lgLayout}
          onResize={(delta) => commit(leftRem, rightRem + delta)}
        />

        <aside className="order-2 flex min-h-[36rem] flex-col border-t border-border/50 bg-background lg:order-none lg:min-h-0 lg:overflow-hidden lg:border-l lg:border-t-0">
          <TracePane
            centerTab={centerTab}
            onCopyPayload={handleCopyPayload}
            document={parseState.document}
            gallerySources={effectiveGallerySources}
            onPreviewPathSelect={handlePreviewPathSelect}
            onPreviewSlideSelect={handlePreviewSlideSelect}
            onRetryRun={handleRetryRun}
            onSelectRun={setSelectedRunId}
            onUseGalleryCandidate={handleGalleryApply}
            onOpenLibrary={(kind) => openLibraryLauncher(kind)}
            payloadPreview={payloadPreview}
            rejectedRunCount={rejectedRunCount}
            runs={runs}
            selectedRun={selectedRun}
            surfaceError={surfaceError ?? localWorkspaceWarning}
            issues={validationIssues}
            onJumpToPath={jumpToPath}
            previewDocument={previewDocument}
            selectedPreviewSlideIndex={selectedPreviewSlideIndex}
            selectionPath={rightRailSelectionPath}
            selectionRows={selectionRows}
            selectionTypeSignature={selectionTypeSignature}
            selectionPinned={pinnedSelection}
            onTogglePin={togglePin}
            copiedPayload={copiedPayload}
          />
        </aside>
      </main>
      <LibraryLauncher
        document={parseState.document}
        gallerySources={effectiveGallerySources}
        initialKind={libraryLauncher.kind}
        onAddSource={handleLibrarySourceAdd}
        onOpenChange={(open) => setLibraryLauncher((current) => ({ ...current, open }))}
        onSetDefault={handleLibraryDefault}
        onUse={
          rightRailSelectionPath
            ? (item) => {
                void handleGalleryApply(rightRailSelectionPath, item);
                setLibraryLauncher((current) => ({ ...current, open: false }));
              }
            : undefined
        }
        open={libraryLauncher.open}
        targetPath={rightRailSelectionPath}
      />
    </div>
  );
}

function AuthorWorkspaceStrip({
  chrome,
  copiedJson,
  copiedShare,
  copiedThreadId,
  currentOpfDocumentId,
  filename,
  filenameEditable,
  latestOpfDocumentId,
  onCommitFilename,
  onCopyJson,
  onCopyThreadId,
  onExportJson,
  onExportMarkdown,
  onExportPptx,
  onExportYaml,
  onNewThread,
  onSaveLocalToAccount,
  onShare,
  overflowMenu,
  pptxBusy,
  pptxEnabled,
  saveLocalBusy,
  signedIn,
  storageMode,
  threadId,
  versionLabel,
  versions,
  onSelectVersion,
}: {
  chrome?: ReactNode;
  copiedJson: boolean;
  copiedShare: boolean;
  copiedThreadId: boolean;
  currentOpfDocumentId: string | null;
  filename: string;
  filenameEditable: boolean;
