function HeaderVersionMenu({
  currentOpfDocumentId,
  latestOpfDocumentId,
  onSelectVersion,
  versionLabel,
  versions,
}: {
  currentOpfDocumentId: string | null;
  latestOpfDocumentId: string | null;
  onSelectVersion: (documentId: string) => void;
  versionLabel: string;
  versions: PublicAuthorOpfDocument[];
}) {
  const [open, setOpen] = useState(false);
  const [menuStyle, setMenuStyle] = useState<CSSProperties>(() => headerChipMenuStyle(null));
  const containerRef = useRef<HTMLDivElement | null>(null);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const menuRef = useRef<HTMLDivElement | null>(null);

  const close = useCallback(() => setOpen(false), []);

  useEffect(() => {
    if (!open) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") close();
    };
    const onClick = (event: MouseEvent) => {
      const target = event.target as Node;
      if (containerRef.current?.contains(target) || menuRef.current?.contains(target)) return;
      close();
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("mousedown", onClick);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("mousedown", onClick);
    };
  }, [close, open]);

  const menu = open ? (
    <div
      ref={menuRef}
      role="menu"
      aria-label="OPF versions"
      style={menuStyle}
      className="z-[1000] overflow-hidden rounded-lg border border-border bg-popover py-1 text-xs shadow-2xl shadow-black/40"
    >
      {versions.map((version) => {
        const current = version.id === currentOpfDocumentId;
        const latest = version.id === latestOpfDocumentId;
        return (
          <button
            key={version.id}
            type="button"
            role="menuitem"
            aria-current={current ? "true" : undefined}
            onClick={() => {
              onSelectVersion(version.id);
              close();
            }}
            className={cn(
              "grid w-full grid-cols-[3rem_minmax(0,1fr)_auto] items-center gap-2 px-3 py-2 text-left font-mono transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
              current ? "bg-muted/45 text-foreground" : "text-muted-foreground hover:bg-muted/35 hover:text-foreground"
            )}
          >
            <span className="text-foreground">v{version.version}</span>
            <span className="min-w-0 truncate">
              {current ? "current" : latest ? "latest" : "history"}
            </span>
            <span className="text-[10px] text-muted-foreground/80">
              {formatDateTime(version.createdAt)} · {shortId(version.id)}
            </span>
          </button>
        );
      })}
    </div>
  ) : null;

  return (
    <div ref={containerRef} className="relative shrink-0">
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={(event) => {
          if (!open) setMenuStyle(headerChipMenuStyle(event.currentTarget));
          setOpen((prev) => !prev);
        }}
        className={cn(
          "inline-flex h-8 items-center gap-1 rounded-full border border-border bg-background px-3 font-mono text-xs text-foreground transition-colors hover:bg-muted/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          open && "border-foreground/30 bg-muted/40"
        )}
      >
        {versionLabel}
        <ChevronDown className="size-3" aria-hidden />
      </button>
      {open && typeof document !== "undefined" && menu ? createPortal(menu, document.body) : null}
    </div>
  );
}

