}

function GalleryCardFooter({ item }: { item: GalleryItem }) {
  return (
    <div className="min-w-0 px-2 py-1.5">
      <div className="flex min-w-0 items-center justify-between gap-2 font-mono text-xs">
        <span className="min-w-0 truncate font-semibold text-foreground">{item.label}</span>
        <span className="shrink-0 text-muted-foreground">{item.subtitle}</span>
